/**
 * Validate one identity.v1 fixture with the generated schema and Rust semantics.
 *
 * Generated by scripts/generate_bindings.py. Do not edit bindings/typescript/check.ts.
 */
import Ajv2020 from "ajv/dist/2020.js";
import { readFileSync } from "node:fs";
import schema from "./schema.json" with { type: "json" };

const I64_MIN = -(1n << 63n);
const I64_MAX = (1n << 63n) - 1n;
const U64_MAX = (1n << 64n) - 1n;
const SAFE = BigInt(Number.MAX_SAFE_INTEGER);
const MAX_TTL_MS = 3_600_000n;

type JsonValue = null | boolean | string | bigint | JsonValue[] | { [key: string]: JsonValue };
type Fixture = { kind: string; value: JsonValue };
type SchemaDocument = { $schema: string; $defs: Record<string, unknown> };
type Parser = { index: number; source: string };

const documentSchema = schema as SchemaDocument;

function parseJson(source: string): JsonValue {
  const parser: Parser = { index: 0, source };
  const value = parseValue(parser);
  whitespace(parser);
  if (parser.index !== source.length) throw new Error("trailing JSON data");
  return value;
}

function whitespace(parser: Parser): void {
  while (/\s/.test(parser.source[parser.index] ?? "") && parser.index < parser.source.length) parser.index += 1;
}

function parseValue(parser: Parser): JsonValue {
  whitespace(parser);
  const char = parser.source[parser.index];
  if (char === '"') return parseString(parser);
  if (char === "{") return parseObject(parser);
  if (char === "[") return parseArray(parser);
  if (parser.source.startsWith("true", parser.index)) { parser.index += 4; return true; }
  if (parser.source.startsWith("false", parser.index)) { parser.index += 5; return false; }
  if (parser.source.startsWith("null", parser.index)) { parser.index += 4; return null; }
  return parseNumber(parser);
}

function parseString(parser: Parser): string {
  const start = parser.index++;
  while (parser.index < parser.source.length) {
    const char = parser.source[parser.index++];
    if (char === "\\") parser.index += 1;
    else if (char === '"') return JSON.parse(parser.source.slice(start, parser.index)) as string;
  }
  throw new Error("unterminated string");
}

function parseObject(parser: Parser): { [key: string]: JsonValue } {
  parser.index += 1;
  const result: { [key: string]: JsonValue } = Object.create(null) as { [key: string]: JsonValue };
  const keys = new Set<string>();
  whitespace(parser);
  if (parser.source[parser.index] === "}") { parser.index += 1; return result; }
  while (true) {
    whitespace(parser);
    if (parser.source[parser.index] !== '"') throw new Error("object key must be a string");
    const key = parseString(parser);
    if (keys.has(key)) throw new Error(`duplicate key ${key}`);
    keys.add(key);
    whitespace(parser);
    if (parser.source[parser.index++] !== ":") throw new Error("expected colon");
    result[key] = parseValue(parser);
    whitespace(parser);
    const next = parser.source[parser.index++];
    if (next === "}") return result;
    if (next !== ",") throw new Error("expected comma");
  }
}

function parseArray(parser: Parser): JsonValue[] {
  parser.index += 1;
  const result: JsonValue[] = [];
  whitespace(parser);
  if (parser.source[parser.index] === "]") { parser.index += 1; return result; }
  while (true) {
    result.push(parseValue(parser));
    whitespace(parser);
    const next = parser.source[parser.index++];
    if (next === "]") return result;
    if (next !== ",") throw new Error("expected comma");
  }
}

function parseNumber(parser: Parser): bigint {
  const rest = parser.source.slice(parser.index);
  const matched = /^-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?/.exec(rest);
  if (matched === null || /[.eE]/.test(matched[0])) throw new Error("numbers must use integer JSON syntax");
  parser.index += matched[0].length;
  return BigInt(matched[0]);
}

function isObject(value: JsonValue): value is { [key: string]: JsonValue } {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function validateNumbers(value: JsonValue): void {
  if (typeof value === "bigint") {
    if (value < I64_MIN || value > U64_MAX) throw new Error("integer outside i64/u64 range");
  } else if (Array.isArray(value)) {
    for (const child of value) validateNumbers(child);
  } else if (isObject(value)) {
    for (const child of Object.values(value)) validateNumbers(child);
  }
}

function requireI64(value: JsonValue | undefined, field: string): bigint {
  if (typeof value !== "bigint" || value < I64_MIN || value > I64_MAX) throw new Error(`${field} must be an i64 integer`);
  return value;
}

function validateSemantics(fixture: Fixture): void {
  validateNumbers(fixture.value);
  if (!isObject(fixture.value)) return;
  const value = fixture.value;
  if (fixture.kind === "Attestation" || fixture.kind === "SessionKey") {
    const session = value.session;
    if (!isObject(session) || value.node !== session.node) throw new Error("bound node must equal the session node");
    const issued = requireI64(value.issued_at, "issued_at");
    const expires = requireI64(value.expires_at, "expires_at");
    const ttl = expires - issued;
    if (ttl <= 0n || ttl > MAX_TTL_MS) throw new Error("expiry must be after issued_at and at most 1 hour later");
  } else if (fixture.kind === "SessionEnd") {
    requireI64(value.ended_at, "ended_at");
  }
}

function schemaValue(value: JsonValue): unknown {
  if (typeof value === "bigint") return value < -SAFE || value > SAFE ? 0 : Number(value);
  if (Array.isArray(value)) return value.map(schemaValue);
  if (isObject(value)) return Object.fromEntries(Object.entries(value).map(([key, child]) => [key, schemaValue(child)]));
  return value;
}

const ajv = new Ajv2020({ strict: false, allErrors: true });
const validators = new Map<string, (data: unknown) => boolean>();

function validatorFor(kind: string): (data: unknown) => boolean {
  const cached = validators.get(kind);
  if (cached !== undefined) return cached;
  const validate = ajv.compile({
    $schema: documentSchema.$schema,
    $defs: documentSchema.$defs,
    $ref: `#/$defs/${kind}`,
  });
  const wrapped = (data: unknown) => validate(data) === true;
  validators.set(kind, wrapped);
  return wrapped;
}

try {
  const parsed = parseJson(readFileSync(process.argv[2], "utf8"));
  if (!isObject(parsed) || typeof parsed.kind !== "string" || parsed.value === undefined) throw new Error("invalid fixture envelope");
  const fixture: Fixture = { kind: parsed.kind, value: parsed.value };
  validateSemantics(fixture);
  console.log(validatorFor(fixture.kind)(schemaValue(fixture.value)) ? "accept" : "reject");
} catch {
  console.log("reject");
}
